package com.example.demo;

import java.util.Map;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class EntryController {
    private final EntryService service;

    public EntryController(EntryService service) {
        this.service = service;
    }

    @GetMapping("/entries/{id}")
    public Map<String, String> entry(@PathVariable("id") long id) {
        return Map.of("title", service.title(id));
    }
}

package com.example.demo;

public interface EntryService {
    String title(long id);
}

package com.example.demo;
import org.springframework.stereotype.Service;
@Service
public class DefaultEntryService implements EntryService {
    public String title(long id) { return "First entry"; }
}

package com.example.demo;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.test.web.servlet.MockMvc;
import static org.mockito.Mockito.when;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@WebMvcTest(EntryController.class)
class EntryControllerTest {
    @Autowired
    private MockMvc mvc;

    @MockitoBean
    private EntryService service;

    @Test
    void returnsEntryTitle() throws Exception {
        when(service.title(7L)).thenReturn("First entry");

        mvc.perform(get("/entries/7"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.title").value("First entry"));
    }
}

package com.example.demo;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

@SpringBootApplication
public class DemoApplication {
    public static void main(String[] args) {
        SpringApplication.run(DemoApplication.class, args);
    }
}
